{
  "conversations": [
    {
      "title": "State my dietary restrictions",
      "lines": [
        { "speaker": "you", "text": "I'm vegan." },
        { "speaker": "partner", "text": "Are you okay with fish broth?" },
        { "speaker": "you", "text": "No, I don't eat fish or meat." },
        { "speaker": "you", "text": "No animal products at all, please.", "or": true },
        { "speaker": "partner", "text": "Got it." }
      ]
    },
    {
      "title": "Ask about hidden ingredients",
      "lines": [
        { "speaker": "you", "text": "Does this have dairy in it?" },
        { "speaker": "partner", "text": "Yes, it contains butter." },
        { "speaker": "partner", "text": "No, it's completely plant-based.", "or": true },
        { "speaker": "you", "text": "What about egg or honey?" },
        { "speaker": "partner", "text": "There's no egg, but it has honey." },
        { "speaker": "partner", "text": "Neither of those are in it.", "or": true }
      ]
    },
    {
      "title": "Order vegan dishes",
      "lines": [
        { "speaker": "you", "text": "I'll take the vegetable ramen, please." },
        { "speaker": "partner", "text": "The broth is made with kelp." },
        { "speaker": "you", "text": "That's great." },
        { "speaker": "you", "text": "Could you make it without bonito flakes?", "or": true },
        { "speaker": "partner", "text": "Sure. Anything else?" },
        { "speaker": "you", "text": "That's everything, thank you." }
      ]
    }
  ],
  "vocab": [
    "vegan",
    "meat",
    "fish",
    "dairy",
    "egg",
    "honey",
    "butter",
    "broth",
    "vegetable",
    "plant-based",
    "ingredient",
    "contain",
    "without",
    "kelp"
  ]
}
